#!/bin/bash
set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYREMOTE'
import base64, hashlib, io, json, os, stat, subprocess, sys, tarfile, time
from pathlib import Path
phase = Path('/home/loosqk/robot-checks/position-return-20261010-r1/base-firmware-read-r15')
payload = {'candidate/base_firmware_read6_r15.py': {'sha256': '39506725bc4008f018e9aa8af615e8f64a6bd3a7974f3433f585599df475b88b', 'bytes': 16721, 'base64': ''}, 'candidate/test_base_firmware_read6_r15.py': {'sha256': 'd6389ccffbab724cdb1540ce21e96ad494d3157be4820a5fc0f3f4acb11a7eeb', 'bytes': 12565, 'base64': ''}, 'candidate/config-template-r15.json': {'sha256': 'e5f8954fb6e49279008c0d9d9e07f04b5439074d70c35bb703afed9b5a604a4a', 'bytes': 1246, 'base64': ''}, '.verify/position_return_2026-10-10_r6/preparation/head1-p24-wire-r6.go.json': {'sha256': 'f523c7bf976bf9ae78d18c902ca333f8156e2d1c374e2a9fb61a1b688bd344a6', 'bytes': 1211, 'base64': ''}, 'boot/prepare_base_firmware_read6_r15.py': {'sha256': '9ab7a19a0a099bc383a7cb9d3eee88bd49a1856da6a87196972425cbf15af914', 'bytes': 12319, 'base64': ''}}
phase.mkdir(mode=0o700, exist_ok=False)
for name, row in payload.items():
    relative = Path(name)
    assert not relative.is_absolute() and '..' not in relative.parts
    raw = base64.b64decode(row['base64'], validate=True)
    assert len(raw) == row['bytes'] and hashlib.sha256(raw).hexdigest() == row['sha256']
    path = phase / relative
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    with path.open('xb') as f: f.write(raw); f.flush(); os.fsync(f.fileno())
boot = phase / 'boot'
launcher = boot / 'launch_software_prepare_r15.sh'
launcher.write_text('#!/bin/bash\nset -eu\nexport PYTHONDONTWRITEBYTECODE=1\ntmux set-option -p remain-on-exit on\nexec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 '+str(boot / 'prepare_base_firmware_read6_r15.py')+' > '+str(boot / 'driver.log')+' 2>&1\n')
receipts = []
def run(name, argv):
    start = time.time_ns()
    child = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = child.communicate(); code = child.wait()
    row = {'name': name, 'argv': argv, 'pid': child.pid, 'started_ns': start, 'finished_ns': time.time_ns(), 'exit_code': code, 'reaped': True, 'signals_sent': [], 'stdout': stdout.decode(), 'stderr': stderr.decode()}
    receipts.append(row)
    return row
start = run('start-software-only', ['tmux', 'new-session', '-d', '-s', 'base-read6-software-20261011-r15', '-P', '-F', '#{session_name}|#{window_id}|#{pane_id}|#{pane_pid}', 'bash '+str(launcher)])
assert start['exit_code'] == 0 and not start['stderr']
session, window, pane, pid = start['stdout'].strip().split('|'); pid = int(pid)
deadline = time.monotonic() + 120
terminal = None
while time.monotonic() < deadline:
    row = run('observe-owned-pane', ['tmux', 'display-message', '-p', '-t', pane, '#{session_name}|#{window_id}|#{pane_id}|#{pane_pid}|#{pane_dead}|#{pane_dead_status}'])
    assert row['exit_code'] == 0 and not row['stderr']
    fields = row['stdout'].strip().split('|')
    assert fields[:4] == [session, window, pane, str(pid)]
    if fields[4] == '1': terminal = row['stdout'].strip(); break
    time.sleep(0.5)
assert terminal is not None, '软件进程未自然结束，保留pane，不发信号或重试'
exit_code = int(terminal.split('|')[-1])
(boot / 'terminal.json').write_text(json.dumps({'terminal': terminal, 'driver_pid': pid, 'exit_code': exit_code, 'same_ssh_children': receipts}, ensure_ascii=False, indent=2)+'\n')
reclaim = run('reclaim-only-natural-dead-owned-pane', ['tmux', 'kill-pane', '-t', pane])
assert reclaim['exit_code'] == 0
(boot / 'reclaim.json').write_text(json.dumps(reclaim, ensure_ascii=False, indent=2)+'\n')
buffer = io.BytesIO()
with tarfile.open(fileobj=buffer, mode='w:gz') as tar:
    for path in sorted(phase.rglob('*')):
        assert not path.is_symlink()
        if path.is_file(): tar.add(path, arcname=str(path.relative_to(phase)), recursive=False)
raw = buffer.getvalue()
with tarfile.open(fileobj=io.BytesIO(raw)) as tar: count = sum(m.isfile() for m in tar)
result_path = phase / 'prepare-result-r15.json'
result = json.loads(result_path.read_text()) if result_path.exists() else None
print(json.dumps({'status': 'SOFTWARE_PREPARATION_COLLECTED', 'driver_pid': pid, 'pane': pane, 'exit_code': exit_code, 'archive_sha256': hashlib.sha256(raw).hexdigest(), 'archive_bytes': len(raw), 'archive_files': count, 'result': result, 'archive_base64': base64.b64encode(raw).decode()}, ensure_ascii=False), flush=True)
sys.exit(exit_code)

PYREMOTE
